import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 현금출납장은 계정과목 명칭이 '현금'인 분개만 보인다.
const CASH_ACCOUNT_NAME = '현금';
// 가정: 승인해제된 전표는 장부에서 제외한다.
const LEDGER_TYPES = ['분개장', '일계표', '월계표', '총계정원장', '현금출납장', '계정별 원장'];
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const ID_RE = /^\d+$/;

const LINES_FROM = `
  FROM journal_voucher jv
  JOIN voucher_line vl ON vl.journal_voucher_id = jv.journal_voucher_id
  JOIN account_item ai ON ai.account_item_id = vl.account_item_id
  WHERE jv.voucher_date BETWEEN CAST(:dateFrom AS date) AND CAST(:dateTo AS date)
    AND jv.status <> '승인해제'
    AND (CAST(:accountItemId AS bigint) IS NULL OR vl.account_item_id = CAST(:accountItemId AS bigint))`;
const MGMT_FILTER = `
    AND (CAST(:managementItemId AS bigint) IS NULL OR vl.management_item_id = CAST(:managementItemId AS bigint))`;
const CASH_FILTER = `
    AND ai.account_name = :cashName`;

const DETAIL_SELECT = `
  SELECT to_char(jv.voucher_date, 'YYYY-MM-DD') AS "voucherDate",
    jv.voucher_no AS "voucherNo",
    ai.account_code AS "accountCode",
    ai.account_name AS "accountName",
    vl.dc_type AS "dcType",
    vl.amount AS "amount",
    vl.summary AS "summary",
    vl.management_item_value AS "managementItemValue"`;

const DAILY_SELECT = `
  SELECT to_char(jv.voucher_date, 'YYYY-MM-DD') AS "voucherDate",
    CAST(NULL AS varchar) AS "voucherNo",
    ai.account_code AS "accountCode",
    ai.account_name AS "accountName",
    vl.dc_type AS "dcType",
    SUM(vl.amount) AS "amount",
    CAST(NULL AS varchar) AS "summary",
    CAST(NULL AS varchar) AS "managementItemValue"`;
const DAILY_GROUP = `
  GROUP BY jv.voucher_date, ai.account_code, ai.account_name, vl.dc_type`;

const MONTHLY_SELECT = `
  SELECT to_char(date_trunc('month', jv.voucher_date), 'YYYY-MM-DD') AS "voucherDate",
    CAST(NULL AS varchar) AS "voucherNo",
    ai.account_code AS "accountCode",
    ai.account_name AS "accountName",
    vl.dc_type AS "dcType",
    SUM(vl.amount) AS "amount",
    CAST(NULL AS varchar) AS "summary",
    CAST(NULL AS varchar) AS "managementItemValue"`;
const MONTHLY_GROUP = `
  GROUP BY date_trunc('month', jv.voucher_date), ai.account_code, ai.account_name, vl.dc_type`;

const ORDER_BY_DATE = `ORDER BY "voucherDate", "voucherNo", "accountCode", "dcType"`;
const ORDER_BY_ACCOUNT = `ORDER BY "accountCode", "voucherDate", "voucherNo", "dcType"`;

function text(v: unknown): string {
  return v === undefined || v === null ? '' : String(v).trim();
}

function requireDate(v: string, label: string): void {
  if (!DATE_RE.test(v)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) YYYY-MM-DD 형식으로 입력해 주세요.');
  }
}

function optionalId(v: string, label: string): string | null {
  if (v === '') {
    return null;
  }
  if (!ID_RE.test(v)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return v;
}

function pagingOf(q: Record<string, unknown>): { page: number; size: number } {
  const pageText = text(q['page']);
  const sizeText = text(q['size']);
  const page = pageText === '' ? 0 : Number(pageText);
  let size = sizeText === '' ? 20 : Number(sizeText);
  if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
  }
  if (size > 200) {
    size = 200;
  }
  return { page, size };
}

type Db = { query: (sql: string, params?: Record<string, unknown>) => Promise<any[]> };

async function ensurePeriod(db: Db, dateFrom: string, dateTo: string): Promise<void> {
  const rows = await db.query(
    `SELECT CAST(:dateFrom AS date) > CAST(:dateTo AS date) AS "invalid"`,
    { dateFrom, dateTo },
  );
  if (rows[0] && rows[0]['invalid'] === true) {
    throw new ApiError(422, 'INVALID_PERIOD', '시작일은 종료일보다 늦을 수 없습니다.');
  }
}

@Controller('api/v1')
export class FnSfr00805Controller {
  @Get('/account-ledgers')
  async listAccountLedgers(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '임직원');
    const q = checks.queryOf(req.query);
    const ledgerType = text(q['ledgerType']);
    const dateFrom = text(q['dateFrom']);
    const dateTo = text(q['dateTo']);
    if (!LEDGER_TYPES.includes(ledgerType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '장부 종류를 선택해 주세요.');
    }
    requireDate(dateFrom, '조회 시작일');
    requireDate(dateTo, '조회 종료일');
    const accountItemId = optionalId(text(q['accountItemId']), '계정과목');
    const managementItemId = optionalId(text(q['managementItemId']), '관리항목');
    const { page, size } = pagingOf(q);
    return transaction(async (db) => {
      await ensurePeriod(db, dateFrom, dateTo);
      const params: Record<string, unknown> = { dateFrom, dateTo, accountItemId, managementItemId };
      let where = LINES_FROM + MGMT_FILTER;
      if (ledgerType === '현금출납장') {
        where = where + CASH_FILTER;
        params['cashName'] = CASH_ACCOUNT_NAME;
      }
      let inner = DETAIL_SELECT + where;
      let order = ORDER_BY_DATE;
      if (ledgerType === '일계표') {
        inner = DAILY_SELECT + where + DAILY_GROUP;
      } else if (ledgerType === '월계표') {
        inner = MONTHLY_SELECT + where + MONTHLY_GROUP;
      } else if (ledgerType === '총계정원장' || ledgerType === '계정별 원장') {
        order = ORDER_BY_ACCOUNT;
      }
      const countRows = await db.query('SELECT COUNT(*) AS "total" FROM (' + inner + ') t', params);
      const items = await db.query(
        'SELECT * FROM (' + inner + ') t ' + order + ' LIMIT :size OFFSET :offset',
        { ...params, size, offset: page * size },
      );
      return { items, page, size, total: Number(countRows[0]['total']) };
    });
  }

  @Get('/account-ledgers/trends')
  async listAccountTrends(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '임직원');
    const q = checks.queryOf(req.query);
    const dateFrom = text(q['dateFrom']);
    const dateTo = text(q['dateTo']);
    requireDate(dateFrom, '조회 시작일');
    requireDate(dateTo, '조회 종료일');
    const accountItemId = optionalId(text(q['accountItemId']), '계정과목');
    const { page, size } = pagingOf(q);
    return transaction(async (db) => {
      await ensurePeriod(db, dateFrom, dateTo);
      const params: Record<string, unknown> = { dateFrom, dateTo, accountItemId };
      // 결정: 기간은 월(YYYY-MM), 금액 합계는 차변 - 대변, 증감액은 직전 기간 대비 (첫 기간은 전기 0으로 본다. 가정)
      const inner = `
  SELECT g.account_name AS "accountName",
    g.period AS "period",
    g.total AS "totalAmount",
    g.total - COALESCE(LAG(g.total) OVER (PARTITION BY g.account_code ORDER BY g.period), 0) AS "changeAmount"
  FROM (
    SELECT ai.account_code AS account_code,
      ai.account_name AS account_name,
      to_char(jv.voucher_date, 'YYYY-MM') AS period,
      SUM(CASE WHEN vl.dc_type = 'DEBIT' THEN vl.amount ELSE -vl.amount END) AS total` + LINES_FROM + `
    GROUP BY ai.account_code, ai.account_name, to_char(jv.voucher_date, 'YYYY-MM')
  ) g`;
      const countRows = await db.query('SELECT COUNT(*) AS "total" FROM (' + inner + ') t', params);
      const items = await db.query(
        'SELECT * FROM (' + inner + ') t ORDER BY "accountName", "period" LIMIT :size OFFSET :offset',
        { ...params, size, offset: page * size },
      );
      return { items, page, size, total: Number(countRows[0]['total']) };
    });
  }
}

