import { useState } from 'react';
import {
  call,
  useData,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  Select,
  DateInput,
  LookupSelect,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const LEDGER_TYPES: [string, string][] = [
  ['분개장', '분개장'],
  ['일계표', '일계표'],
  ['월계표', '월계표'],
  ['총계정원장', '총계정원장'],
  ['현금출납장', '현금출납장'],
  ['계정별 원장', '계정별 원장'],
];

const EMPTY_FORM: Row = {
  ledgerType: '분개장',
  dateFrom: '',
  dateTo: '',
  accountItemId: '',
  managementItemId: '',
};

const SIZE = 20;

function dcLabel(v: unknown): string {
  if (v === 'DEBIT') {
    return '차변';
  }
  if (v === 'CREDIT') {
    return '대변';
  }
  return '';
}

export default function FnSfr00805Page({ role, notify }: PageProps) {
  const [form, setForm] = useState<Row>(EMPTY_FORM);
  const [applied, setApplied] = useState<Row | null>(null);
  const [formError, setFormError] = useState('');
  const [page, setPage] = useState(0);
  const [tpage, setTpage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);

  const ledger = useData<Page | undefined>(
    async () => {
      if (!applied) {
        return undefined;
      }
      return call<Page>('GET', '/account-ledgers', role, undefined, { ...applied, page, size: SIZE });
    },
    [applied, page, role],
  );

  const trends = useData<Page | undefined>(
    async () => {
      if (!applied) {
        return undefined;
      }
      return call<Page>('GET', '/account-ledgers/trends', role, undefined, {
        dateFrom: applied['dateFrom'],
        dateTo: applied['dateTo'],
        accountItemId: applied['accountItemId'],
        page: tpage,
        size: SIZE,
      });
    },
    [applied, tpage, role],
  );

  function setField(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  function search() {
    if (!form['dateFrom'] || !form['dateTo']) {
      setFormError('조회 시작일과 종료일을 입력해 주세요.');
      return;
    }
    if (String(form['dateFrom']) > String(form['dateTo'])) {
      setFormError('시작일은 종료일보다 늦을 수 없습니다.');
      return;
    }
    setFormError('');
    setPage(0);
    setTpage(0);
    setApplied({ ...form });
    notify('장부를 조회했습니다.');
  }

  function reset() {
    setForm(EMPTY_FORM);
    setFormError('');
    setApplied(null);
    setPage(0);
    setTpage(0);
  }

  const ledgerRows = ledger.data ? ledger.data.items : [];
  const trendRows = trends.data ? trends.data.items : [];

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>조회 현황</h2>
        <Tiles
          items={[
            ['장부 건수', <Num value={ledger.data ? ledger.data.total : 0} />],
            ['변동추이 건수', <Num value={trends.data ? trends.data.total : 0} />],
          ]}
        />
      </section>

      <section className='box span-8'>
        <h2>계정별 장부</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='장부 종류' required>
            <Select
              value={form['ledgerType']}
              onChange={(v) => setField('ledgerType', v)}
              options={LEDGER_TYPES}
            />
          </Field>
          <Field label='조회 시작일' required>
            <DateInput value={form['dateFrom']} onChange={(v) => setField('dateFrom', v)} />
          </Field>
          <Field label='조회 종료일' required>
            <DateInput value={form['dateTo']} onChange={(v) => setField('dateTo', v)} />
          </Field>
          <Field label='계정과목'>
            <LookupSelect
              table='account_item'
              role={role}
              value={form['accountItemId']}
              onChange={(v) => setField('accountItemId', v)}
            />
          </Field>
          <Field label='관리항목'>
            <LookupSelect
              table='management_item'
              role={role}
              value={form['managementItemId']}
              onChange={(v) => setField('managementItemId', v)}
            />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {ledger.error ? <ErrorText text={ledger.error} /> : null}
        <Band total={ledger.data ? ledger.data.total : 0} />
        <DataTable
          columns={[
            { key: 'voucherDate', label: '전표일자', render: (r) => <DateText value={r['voucherDate']} /> },
            { key: 'voucherNo', label: '전표번호' },
            { key: 'accountCode', label: '계정과목 코드' },
            { key: 'accountName', label: '계정과목 명칭' },
            { key: 'dcType', label: '차대 구분', render: (r) => <span>{dcLabel(r['dcType'])}</span> },
            { key: 'amount', label: '금액', render: (r) => <Num value={r['amount']} /> },
            { key: 'summary', label: '적요' },
            { key: 'managementItemValue', label: '관리항목값' },
          ]}
          rows={ledgerRows}
          onRowClick={(r) => setSelected(r)}
          empty={applied ? '조회된 장부가 없습니다.' : '조회 조건을 입력하고 조회를 눌러 주세요.'}
        />
        <Pager
          page={page}
          size={SIZE}
          total={ledger.data ? ledger.data.total : 0}
          onPage={setPage}
        />
      </section>

      <section className='box span-4'>
        <h2>주요계정 변동추이</h2>
        {trends.error ? <ErrorText text={trends.error} /> : null}
        <DataTable
          columns={[
            { key: 'accountName', label: '계정과목 명칭' },
            { key: 'period', label: '집계 기간' },
            { key: 'totalAmount', label: '기간 금액 합계', render: (r) => <Num value={r['totalAmount']} /> },
            { key: 'changeAmount', label: '전기 대비 증감액', render: (r) => <Num value={r['changeAmount']} /> },
          ]}
          rows={trendRows}
          empty={applied ? '조회된 변동추이가 없습니다.' : '조회 조건을 입력해 주세요.'}
        />
        <Pager
          page={tpage}
          size={SIZE}
          total={trends.data ? trends.data.total : 0}
          onPage={setTpage}
        />
      </section>

      {selected ? (
        <Drawer title='장부 상세' onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['전표일자', <DateText value={selected['voucherDate']} />],
              ['전표번호', String(selected['voucherNo'] ?? '')],
              ['계정과목 코드', String(selected['accountCode'] ?? '')],
              ['계정과목 명칭', String(selected['accountName'] ?? '')],
              ['차대 구분', dcLabel(selected['dcType'])],
              ['금액', <Num value={selected['amount']} />],
              ['적요', String(selected['summary'] ?? '')],
              ['관리항목값', String(selected['managementItemValue'] ?? '')],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
